"""dev-kit 3.27: one definition of every id (dev_ids.py), ids generated by scripts and checked by sync-plan
(conventions.md §3). The field case: a plan that restarts the milestone numbering in each release.

Run: python3 -I -m unittest .claude/plugins/dev-kit/skills/core/tests/test_ids.py -v
"""
from __future__ import annotations

import json
import os
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

CORE = Path(__file__).resolve().parent.parent
SCRIPTS = CORE / "scripts"
STATE = SCRIPTS / "dev_state.py"
sys.path.insert(0, str(SCRIPTS))
import dev_ids as dids  # noqa: E402


def task(tid: str, title: str = "Step", deps: str = "") -> str:
    return f"### {tid} {title}\n- status: todo\n- deps: {deps}\n- type: feature\n- acceptance:\n  - AC-1: works\n- test_notes: unit\n- files: src/a.py\n\n"


RESTARTED = ("# Plan — shop\n\n## R1 — First\n\n## M1 — Core\nCore.\n\n" + task("T-001", "Core") + "## M2 — Cart\nCart.\n\n"
             + task("T-002", "Cart") + "## R2 — Second\n\n## M1 — Pay\nPay.\n\n" + task("T-003", "Pay")
             + "## M2 — Ship\nShip.\n\n" + task("T-004", "Ship"))


class TestPatterns(unittest.TestCase):
    def test_canonical_forms(self) -> None:
        self.assertEqual(dids.canonical("milestone", "M01"), "M1")
        self.assertEqual(dids.canonical("milestone", "milestone 3"), "M3")
        self.assertEqual(dids.canonical("milestone", "m5.1"), "M5.1")
        self.assertEqual(dids.canonical("release", "Release 02"), "R2")
        self.assertEqual(dids.canonical("task", "t-7"), "T-007")
        self.assertTrue(dids.is_canonical("task", "T-1234"))
        self.assertFalse(dids.is_canonical("milestone", "M01"))
        self.assertIsNone(dids.canonical("milestone", "banana"))

    def test_order_and_next(self) -> None:
        self.assertEqual(sorted(["M6", "M5.1", "M5", "M10"], key=dids.mkey), ["M5", "M5.1", "M6", "M10"])
        self.assertEqual(dids.next_milestone(["M1", "M2"], retired=["M7"]), "M8")
        self.assertEqual(dids.next_milestone([], first=7), "M7")
        self.assertEqual(dids.next_release(["R1", "R0"]), "R2")
        self.assertEqual(dids.next_seq("question", 1, ["Q-001", "Q-002"]), ("Q-003", 4))

    def test_board_gets_the_same_patterns(self) -> None:
        import dev_board as db
        pats = json.loads(db.ids_payload())
        self.assertEqual(pats["task"], dids.TASK)
        self.assertIn("__BOARD_IDS__", (CORE / "shared" / "board" / "index.html").read_text(encoding="utf-8"))


class Project(unittest.TestCase):
    def setUp(self) -> None:
        self.tmp = tempfile.TemporaryDirectory()
        self.root = Path(self.tmp.name).resolve()
        self.dev = self.root / ".dev"
        self.env = {k: v for k, v in os.environ.items() if k not in ("DEV_KIT_NOW", "CLAUDE_CODE_SESSION_ID", "CLAUDE_SESSION_ID")}
        subprocess.run(["git", "init", "-q", "-b", "main"], cwd=self.root, check=True)
        self.ds("init", "--language", "en", "--project", "shop")

    def tearDown(self) -> None:
        self.tmp.cleanup()

    def ds(self, *args: str, expect: int | None = 0) -> subprocess.CompletedProcess:
        p = subprocess.run([sys.executable, "-I", str(STATE), "--root", str(self.root), *args],
                           capture_output=True, text=True, env=self.env)
        if expect is not None:
            self.assertEqual(p.returncode, expect, p.stdout + p.stderr)
        return p

    def state(self) -> dict:
        return json.loads((self.dev / "state.json").read_text(encoding="utf-8"))

    def plan(self, text: str) -> None:
        (self.dev / "plan.md").write_text(text, encoding="utf-8")


class TestSyncPlanIds(Project):
    def test_restarted_numbering_is_renumbered(self) -> None:
        self.plan(RESTARTED)
        chk = json.loads(self.ds("ids", "check", "--json").stdout)
        self.assertFalse(chk["ok"])
        self.assertEqual(len(chk["would_change"]), 2)
        out = self.ds("sync-plan").stdout
        self.assertIn("ids renumbered", out)
        st = self.state()
        self.assertEqual(sorted(st["milestones"], key=dids.mkey), ["M1", "M2", "M3", "M4"])
        self.assertEqual({r["id"]: r["milestones"] for r in st["release_plan"]}, {"R1": ["M1", "M2"], "R2": ["M3", "M4"]})
        self.assertEqual(st["tasks"]["T-003"]["milestone"], "M3")
        self.assertEqual(st["tasks"]["T-001"]["milestone"], "M1")
        text = (self.dev / "plan.md").read_text(encoding="utf-8")
        self.assertIn("## M3 — Pay", text)
        self.assertIn("## M4 — Ship", text)
        self.assertTrue(list((self.dev / "backup").glob("plan-ids-*.md")))
        self.assertIn("Plan ids made canonical and unique", (self.dev / "decisions.md").read_text(encoding="utf-8"))
        self.assertTrue(json.loads(self.ds("ids", "check", "--json").stdout)["ok"])

    def test_copy_with_work_keeps_the_id(self) -> None:
        self.plan(RESTARTED.split("## R2")[0])
        self.ds("sync-plan")
        self.ds("start", "T-001")
        self.plan(RESTARTED.replace("## M1 — Core", "## M1 — Core", 1))
        self.ds("sync-plan")
        st = self.state()
        self.assertEqual(st["tasks"]["T-001"]["milestone"], "M1")
        self.assertEqual(st["tasks"]["T-003"]["milestone"], "M3")

    def test_repeated_ids_with_work(self) -> None:
        self.plan(RESTARTED.split("## R2")[0])
        self.ds("sync-plan")
        self.ds("start", "T-001")
        # a new task written with an id already taken: the copy the state holds (same title) keeps it
        self.plan(RESTARTED.split("## R2")[0] + "## R2 — Second\n\n## M3 — Pay\nPay.\n\n" + task("T-001", "Again"))
        self.ds("sync-plan")
        st = self.state()
        self.assertEqual((st["tasks"]["T-001"]["title"], st["tasks"]["T-001"]["status"]), ("Core", "in_progress"))
        self.assertEqual(st["tasks"]["T-003"]["title"], "Again")
        # same title too: the milestone the state records tells them apart
        self.plan(RESTARTED.split("## R2")[0] + "## R2 — Second\n\n## M3 — Pay\nPay.\n\n" + task("T-003", "Again")
                  + "## M4 — Pay\nPay.\n\n" + task("T-001", "Core"))
        self.ds("sync-plan")
        self.assertEqual(self.state()["tasks"]["T-001"]["milestone"], "M1")
        # a repeated release that was already submitted cannot be renamed: the sync stops
        self.ds("release-submit", "R1", expect=None)
        st = self.state()
        st.setdefault("release_state", {})["R1"] = {"status": "awaiting_approval"}
        (self.dev / "state.json").write_text(json.dumps(st), encoding="utf-8")
        self.plan((self.dev / "plan.md").read_text(encoding="utf-8").replace("## R2 — Second", "## R1 — Again"))
        p = self.ds("sync-plan", expect=1)
        self.assertIn("R1 appears 2 times", p.stderr + p.stdout)

    def test_near_headings_and_titles(self) -> None:
        self.plan("# Plan\n\n## Release 1 — First\n\n## Milestone 01 — Core\nCore.\n\n" + task("T-1", "Core")
                  + "## M2: Cart\nCart.\n\n" + task("T-002", "Cart", deps="T-1"))
        self.ds("sync-plan")
        text = (self.dev / "plan.md").read_text(encoding="utf-8")
        for line in ("## R1 — First", "## M1 — Core", "### T-001 Core", "## M2 — Cart", "- deps: T-001"):
            self.assertIn(line, text)
        st = self.state()
        self.assertEqual(st["tasks"]["T-002"]["deps"], ["T-001"])
        self.assertNotIn("T-1", st["tasks"])

    def test_legacy_id_with_history_is_kept(self) -> None:
        self.plan("# Plan\n\n## R1 — First\n\n## M1 — Core\nCore.\n\n" + task("T-001"))
        self.ds("sync-plan")
        st = self.state()
        st["milestones"]["M01"] = {"title": "Old", "gate": "passed", "qa_runs": 1}
        (self.dev / "state.json").write_text(json.dumps(st), encoding="utf-8")
        self.plan("# Plan\n\n## R1 — First\n\n## M01 — Old\nOld.\n\n" + task("T-001"))
        out = self.ds("sync-plan").stdout
        self.assertIn("legacy", out)
        self.assertIn("## M01 — Old", (self.dev / "plan.md").read_text(encoding="utf-8"))
        self.assertIn("M01", self.state()["ids"]["legacy"])


class TestGeneration(Project):
    def test_add_task_takes_only_the_next_milestone(self) -> None:
        self.plan("# Plan\n\n## R1 — First\n\n## M1 — Core\nCore.\n\n" + task("T-001"))
        self.ds("sync-plan")
        for bad in ("banana", "M01", "M5"):
            p = self.ds("add-task", "--milestone", bad, "--milestone-title", "X", "--title", "t", "--type", "chore", expect=1)
            self.assertIn("next free number: M2", p.stderr)
        self.ds("add-task", "--milestone", "M2", "--milestone-title", "X", "--title", "t", "--type", "chore")

    def test_ids_next(self) -> None:
        self.plan("# Plan\n\n## R1 — First\n\n## M1 — Core\nCore.\n\n" + task("T-001"))
        self.ds("sync-plan")
        self.assertEqual(self.ds("ids", "next", "milestone", "--count", "2").stdout.split(), ["M2", "M3"])
        self.assertEqual(self.ds("ids", "next", "release").stdout.split(), ["R2"])
        self.assertEqual(self.ds("ids", "next", "task").stdout.split(), ["T-002"])

    def test_question_ids_skip_existing(self) -> None:
        q = self.ds("add-question", "first?", "--skill", "prd").stdout.strip().split()[0]
        self.assertEqual(q, "Q-001")
        st = self.state()
        st["next_question_id"] = 1  # a lost counter
        (self.dev / "state.json").write_text(json.dumps(st), encoding="utf-8")
        q2 = self.ds("add-question", "second?", "--skill", "prd").stdout.strip().split()[0]
        self.assertEqual(q2, "Q-002")


if __name__ == "__main__":
    unittest.main()
